SELECT ?point ?class ?ts WHERE {
  ?point a ?class .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  FILTER (str(?class) LIKE '%Power%' || str(?class) LIKE '%Electric%Meter%' || str(?class) LIKE '%Lighting%')
}

SELECT ?point ?class WHERE {
  ?point a ?class .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  FILTER (CONTAINS(str(?point), "Power") || CONTAINS(str(?class),"Power") || CONTAINS(str(?point),"Meter") || CONTAINS(str(?point),"Lighting"))
}

SELECT ?point ?ts WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  FILTER (CONTAINS(str(?point), "Zone_") && CONTAINS(str(?point), "Electric_Power_Sensor"))
}

